120	     * or whose days overlap one, is left out; the others are still made. Returns the periods made, earliest first.
121	     */
122	    @Transactional
123	    public List<Period> generateQuarters(String sheetId, String user, int year) {
124	        sheets.load(sheetId, user);
125	        sheetRows.lockById(sheetId);
126	        List<Period> existing = new ArrayList<>(list(sheetId));
127	        List<Period> made = new ArrayList<>();
128	        for (int quarter = 1; quarter <= 4; quarter++) {
129	            YearMonth start = YearMonth.of(year, quarter * 3 - 2);
130	            addUnlessTaken(sheetId, user, String.format("%04d-Q%d", year, quarter), start.atDay(1),
131	                    start.plusMonths(2).atEndOfMonth(), existing, made);
132	        }
133	        return made;
134	    }
