137	    private void addUnlessTaken(String sheetId, String user, String name, LocalDate first, LocalDate last,
138	            List<Period> existing, List<Period> made) {
139	        if (existing.stream().anyMatch(p -> p.getName().equalsIgnoreCase(name) || p.overlaps(first, last))) {
140	            return;
141	        }
142	        Period period = periods.saveAndFlush(new Period(sheetId, name, first, last));
143	        events.publishEvent(new PeriodAdded(sheetId, user, name, first, last, null));
144	        existing.add(period);
145	        made.add(period);
146	    }
