175	    /**
176	     * Close a period, fixing each person's due-total and carried figure for it (see {@link #carried}), for every person on the sheet, and its own, their sum: the due figures of the claims due by a date inside it that counted (OPEN, PENDING and SETTLED,
177	     * but not an unbound OPEN claim dated within a hold of its person, nor a deferred one) at the end of its last day,
178	     * see {@link Dues#countsAsOf}, added up per person. A soft-closed period is closed with its figures fixed
179	     * afresh. Refused when it is already closed, or for a role the sheet's
180	     * permission matrix does not allow to close. Takes turns with claim changes on the
181	     * sheet, so the total fixed is the one the claims had at that moment.
182	     */
183	    @Transactional
184	    public Period close(String sheetId, String user, long periodId) {
185	        sheetRows.lockById(sheetId);
186	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
187	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
188	        if (!access.allows(sheetId, user, Permission.CLOSE)) {
189	            throw new PeriodRefused("Your role may not close a period on this sheet.");
190	        }
191	        if (period.isClosed()) {
192	            throw new PeriodRefused("The period is already closed.");
193	        }
