199	     * Soft-close an open period: its figures are fixed as a close fixes them, but claims due by a date inside it can
200	     * still be added, edited, opened, settled and voided. Refused when it is already closed or soft-closed, or
201	     * for a role the sheet's permission matrix does not allow to close.
202	     */
203	    @Transactional
204	    public Period softClose(String sheetId, String user, long periodId) {
205	        sheetRows.lockById(sheetId);
206	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
207	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
208	        if (!access.allows(sheetId, user, Permission.CLOSE)) {
209	            throw new PeriodRefused("Your role may not close a period on this sheet.");
210	        }
211	        if (period.isClosed()) {
212	            throw new PeriodRefused("The period is already closed.");
213	        }
214	        if (period.isSoftClosed()) {
215	            throw new PeriodRefused("The period is already soft-closed.");
216	        }
217	        fix(sheetId, user, period, false, true);
