221	    /**
222	     * When the sheet's today is changed and it has grace days, close every open period (neither closed nor
223	     * soft-closed) whose to-date plus the grace days is before the new today, in order of their to-dates, each as a close by hand would.
224	     */
225	    @EventListener
226	    @Transactional
227	    public void on(TodayChanged e) {
228	        Integer grace = sheets.graceDays(e.sheetId());
229	        if (grace == null) {
230	            return;
231	        }
232	        sheetRows.lockById(e.sheetId());
233	        list(e.sheetId()).stream()
234	                .filter(p -> !p.isFixed() && p.getToDate().plusDays(grace).isBefore(e.today()))
235	                .sorted(Comparator.comparing(Period::getToDate))
236	                .forEach(p -> fix(e.sheetId(), e.user(), p, true, false));
