239	    /**
240	     * Each person's carried figure for the period, for every person on the sheet: the due figures as they stand of
241	     * their claims that count on the sheet's today (neither left out by a retirement nor deferred, see
242	     * {@link Dues#counts}) due by a date inside a period ending before it starts and still OPEN or PENDING at the end
243	     * of its last day, by the status log, added up per person, with the opening balances pasted for them in it.
244	     */
245	    private Map<Long, BigDecimal> carried(String sheetId, Period period, Map<Long, Person> byId, RateTable table) {
246	        List<Period> all = list(sheetId);
247	        Map<Long, BigDecimal> carried = new HashMap<>();
248	        byId.keySet().forEach(id -> carried.put(id, BigDecimal.ZERO.setScale(2)));
249	        claims.findBySheetIdOrderByIdDesc(sheetId).stream()
250	                .filter(c -> byId.containsKey(c.getPersonId()))
251	                .filter(c -> all.stream().anyMatch(home -> home.contains(c.getDueBy())
252	                        && home.getToDate().isBefore(period.getFromDate())))
253	                .filter(c -> c.getDeferredUntil() == null || !table.today().isBefore(c.getDeferredUntil()))
254	                .filter(c -> Dues.countsAsOf(c, byId.get(c.getPersonId()).leaves(), table.today(), period.getToDate()))
255	                .filter(c -> {
256	                    ClaimStatus then = Dues.statusAsOf(c, period.getToDate());
257	                    return then == ClaimStatus.OPEN || then == ClaimStatus.PENDING;
258	                })
259	                .forEach(c -> {
260	                    BigDecimal due = Dues.figure(c, byId.get(c.getPersonId())::gradeOn, table);
261	                    if (due != null) {
262	                        carried.merge(c.getPersonId(), due, BigDecimal::add);
263	                    }
264	                });
265	        period.getPersonOpenings().forEach((id, amount) -> {
266	            if (byId.containsKey(id)) {
267	                carried.merge(id, amount, BigDecimal::add);
268	            }
269	        });
270	        carried.replaceAll((id, t) -> t.setScale(2, RoundingMode.HALF_UP));
271	        return carried;
272	    }
