274	    /** Fix the period's due-totals and carried figures as of the end of its last day and close it, or soft-close it. */
275	    private void fix(String sheetId, String user, Period period, boolean auto, boolean soft) {
276	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
277	                .collect(Collectors.toMap(Person::getId, p -> p));
278	        RateTable table = rates.table(sheetId);
279	        Map<Long, BigDecimal> totals = new HashMap<>();
280	        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
281	        claims.findBySheetIdOrderByIdDesc(sheetId).stream()
282	                .filter(c -> period.contains(c.getDueBy())
283	                        && Dues.countsAsOf(c, byId.get(c.getPersonId()).leaves(), table.today(), period.getToDate()))
284	                .forEach(c -> {
285	                    BigDecimal due = Dues.figure(c, byId.get(c.getPersonId())::gradeOn, table);
286	                    if (due != null) {
287	                        totals.merge(c.getPersonId(), due, BigDecimal::add);
288	                    }
289	                });
290	        totals.replaceAll((id, t) -> t.setScale(2, RoundingMode.HALF_UP));
291	        period.close(totals, carried(sheetId, period, byId, table), soft);
292	        BigDecimal total = period.getClosedTotal().setScale(2, RoundingMode.HALF_UP);
293	        periods.flush();
294	        events.publishEvent(new PeriodClosed(sheetId, user, period.getName(), total, auto, soft));
295	    }
