297	    /**
298	     * Reopen a closed or soft-closed period: its due-total and its people's carried figures are live again, the current figures of the claims
299	     * due by a date inside it. Refused unless the sheet's permission matrix allows the user's role (a steward, unless
300	     * set), and when the period is neither closed nor soft-closed.
301	     */
302	    @Transactional
303	    public Period reopen(String sheetId, String user, long periodId) {
304	        sheetRows.lockById(sheetId);
305	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
306	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
307	        if (!access.allows(sheetId, user, Permission.REOPEN)) {
308	            throw new PeriodRefused("Your role may not reopen a period on this sheet.");
309	        }
310	        if (!period.isFixed()) {
311	            throw new PeriodRefused("The period is not closed.");
312	        }
313	        if (period.isLocked()) {
314	            throw new PeriodRefused("The period is locked.");
315	        }
316	        period.reopen();
317	        periods.flush();
318	        events.publishEvent(new PeriodReopened(sheetId, user, period.getName()));
319	        return period;
320	    }
321	
322	    /**
323	     * Lock a period, so it cannot be reopened, or unlock it. Refused unless the user is a steward, and when it is
324	     * already locked (or, to unlock, not locked).
325	     */
326	    @Transactional
327	    public Period lock(String sheetId, String user, long periodId, boolean lock) {
328	        sheetRows.lockById(sheetId);
329	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
330	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
331	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
332	            throw new PeriodRefused("Only a steward may " + (lock ? "lock" : "unlock") + " a period.");
333	        }
334	        if (period.isLocked() == lock) {
335	            throw new PeriodRefused(lock ? "The period is already locked." : "The period is not locked.");
336	        }
337	        period.setLocked(lock);
338	        periods.flush();
339	        events.publishEvent(lock ? new PeriodLocked(sheetId, user, period.getName())
340	                : new PeriodUnlocked(sheetId, user, period.getName()));
341	        return period;
342	    }
343	
344	    /** The closed period whose dates contain the date, if any. */
345	    @Transactional(readOnly = true)
346	    public Optional<Period> closedOn(String sheetId, LocalDate date) {
347	        return list(sheetId).stream().filter(p -> p.isClosed() && p.contains(date)).findFirst();
348	    }
