351	    @Transactional(readOnly = true)
352	    public Optional<Period> softClosedOn(String sheetId, LocalDate date) {
353	        return list(sheetId).stream().filter(p -> p.isSoftClosed() && p.contains(date)).findFirst();
354	    }
