356	    /**
357	     * Refuse a change to a claim due by any of the dates when a closed period contains it. Holds the
358	     * sheet's lock until the transaction ends, so a period cannot close while the change is made.
359	     */
360	    @Transactional
361	    public void requireOpen(String sheetId, LocalDate... dates) {
362	        sheetRows.lockById(sheetId);
363	        for (LocalDate date : dates) {
364	            closedOn(sheetId, date).ifPresent(p -> {
365	                throw new ClosedPeriodRefused(p.getName());
366	            });
367	        }
368	    }
